    /** 결제 승인: 재고와 예약을 함께 차감. */
    public void commitSale(int quantity) {
        stock -= quantity;
        reserved -= quantity;
    }

    /** 환불: 재고 복원. */
    public void restock(int quantity) {
        stock += quantity;
    }

