        for (int i = 0; i < 5; i++) { int n=i; ps.add(ex.submit(() -> payOrder(o,"cp"+n,"t").getStatusCode().value())); }
        cnt = new TreeMap<>(); for (var f: ps) cnt.merge(f.get(),1,Integer::sum);
        System.out.println("PROBE concpay " + cnt + " pgcalls=" + PG.payCallCount());
        ex.shutdown();
    }
}
