24	@RestController
25	@RequestMapping("/api/orders")
26	public class OrderController {
27	
28	    private final OrderService orderService;
29	    private final OrderLifecycleService lifecycleService;
30	    private final IdempotencyService idempotency;
31	
32	    public OrderController(OrderService orderService, OrderLifecycleService lifecycleService,
33	                           IdempotencyService idempotency) {
34	        this.orderService = orderService;
35	        this.lifecycleService = lifecycleService;
36	        this.idempotency = idempotency;
37	    }
38	
39	    @PostMapping
40	    public ResponseEntity<String> create(
41	            @RequestHeader("X-User-Id") @NotBlank @Size(max = 50) String userId,
42	            @RequestHeader("Idempotency-Key") @Size(min = 1, max = 64) String idempotencyKey,
43	            @Valid @RequestBody CreateOrderRequest request) {
44	        String fingerprint = idempotency.fingerprint(userId, "/api/orders", request);
45	        StoredResponse stored = idempotency.execute(IdempotencyScope.CREATE_ORDER, idempotencyKey, fingerprint,
46	                recordId -> orderService.create(userId, request, recordId));
47	        return toResponse(stored);
48	    }
