68	            @RequestHeader(value = "X-User-Id", required = false) String userId,
69	            @Valid @RequestBody PayRequest request) {
70	        String fingerprint = idempotency.fingerprint(userId, "/api/orders/" + id + "/pay", request);
71	        StoredResponse stored = idempotency.execute(IdempotencyScope.PAY_ORDER, idempotencyKey, fingerprint,
72	                recordId -> lifecycleService.pay(id, request.cardToken(), idempotencyKey, recordId));
73	        return toResponse(stored);
