91	    private static ResponseEntity<String> toResponse(StoredResponse stored) {
92	        ResponseEntity.BodyBuilder builder = ResponseEntity.status(HttpStatus.valueOf(stored.status()))
93	                .contentType(MediaType.APPLICATION_JSON);
94	        if (stored.location() != null) {
95	            builder.header(HttpHeaders.LOCATION, stored.location());
96	        }
97	        return builder.body(stored.body());
