1	package com.example.order.order;
2	
3	import com.example.order.common.error.ApiException;
4	import com.example.order.common.error.ErrorCode;
5	import com.example.order.common.time.TimeProvider;
6	import com.example.order.coupon.Coupon;
7	import com.example.order.coupon.CouponPolicy;
8	import com.example.order.coupon.CouponRepository;
9	import com.example.order.idempotency.IdempotencyService;
10	import com.example.order.idempotency.StoredResponse;
11	import com.example.order.product.Product;
12	import java.time.Instant;
13	import java.util.List;
14	import java.util.Map;
15	import org.springframework.dao.DataIntegrityViolationException;
16	import org.springframework.data.domain.Sort;
17	import org.springframework.data.jpa.domain.Specification;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.annotation.Transactional;
20	
21	/** 주문 생성(R3)·조회·목록(R9). */
22	@Service
23	public class OrderService {
24	
25	    private final OrderRepository orderRepository;
26	    private final CouponRepository couponRepository;
27	    private final OrderResourceSupport resources;
28	    private final IdempotencyService idempotency;
29	    private final TimeProvider time;
30	    private final OrderProperties properties;
31	
32	    public OrderService(OrderRepository orderRepository, CouponRepository couponRepository,
33	                        OrderResourceSupport resources, IdempotencyService idempotency,
34	                        TimeProvider time, OrderProperties properties) {
35	        this.orderRepository = orderRepository;
36	        this.couponRepository = couponRepository;
37	        this.resources = resources;
38	        this.idempotency = idempotency;
39	        this.time = time;
40	        this.properties = properties;
41	    }
42	
43	    @Transactional
44	    public StoredResponse create(String userId, CreateOrderRequest request, long idempotencyRecordId) {
45	        Instant now = time.now();
46	        List<CreateOrderRequest.Item> items = request.items();
47	
48	        // 4. 상품 락(id 오름차순) — 없으면 404
49	        Map<Long, Product> products = resources.lockProducts(items.stream().map(CreateOrderRequest.Item::productId).toList());
50	
51	        // 5. 쿠폰 락 — 없으면 404
52	        Coupon coupon = null;
53	        if (request.couponCode() != null) {
54	            coupon = couponRepository.findByCodeForUpdate(request.couponCode())
55	                    .orElseThrow(() -> new ApiException(ErrorCode.COUPON_NOT_FOUND,
56	                            "쿠폰을 찾을 수 없습니다: code=" + request.couponCode()));
57	        }
58	
59	        // 6. 재고 검사 (요청 항목 순서)
60	        for (CreateOrderRequest.Item item : items) {
61	            Product p = products.get(item.productId());
62	            if (p.available() < item.quantity()) {
63	                throw new ApiException(ErrorCode.INSUFFICIENT_STOCK, "상품 " + p.getId() + "의 가용 재고("
64	                        + p.available() + ")가 요청 수량(" + item.quantity() + ")보다 적습니다.");
65	            }
66	        }
67	
68	        // 7. 소계
69	        long subtotal = 0;
70	        for (CreateOrderRequest.Item item : items) {
71	            subtotal = Math.addExact(subtotal,
72	                    Math.multiplyExact(products.get(item.productId()).getPrice(), (long) item.quantity()));
73	        }
74	
75	        // 8. 쿠폰 판정
76	        long discount = 0;
77	        if (coupon != null) {
78	            checkCouponApplicable(coupon, userId, subtotal, now);
79	            discount = CouponPolicy.discount(coupon, subtotal);
80	        }
81	
82	        // 9. 반영
83	        for (CreateOrderRequest.Item item : items) {
84	            products.get(item.productId()).reserve(item.quantity());
85	        }
86	        if (coupon != null) {
87	            coupon.use();
88	        }
89	        Order order = Order.create(userId, coupon == null ? null : coupon.getCode(), subtotal, discount,
90	                now, now.plus(properties.paymentTtl()));
91	        for (int i = 0; i < items.size(); i++) {
92	            CreateOrderRequest.Item item = items.get(i);
93	            order.addItem(i, item.productId(), item.quantity(), products.get(item.productId()).getPrice());
94	        }
95	        try {
96	            orderRepository.saveAndFlush(order);
97	        } catch (DataIntegrityViolationException e) {
98	            if (String.valueOf(e.getMessage()).contains("ux_orders_user_coupon_active")) {
99	                throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
100	            }
101	            throw e;
102	        }
103	
104	        // 10. 멱등 레코드 완료 (같은 트랜잭션)
105	        return idempotency.complete(idempotencyRecordId, 201, OrderResponse.from(order), "/api/orders/" + order.getId());
106	    }
107	
108	    private void checkCouponApplicable(Coupon coupon, String userId, long subtotal, Instant now) {
109	        if (!coupon.isWithinPeriod(now)) {
110	            throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "쿠폰 사용 가능 기간이 아닙니다.");
111	        }
112	        if (subtotal < coupon.getMinOrderAmount()) {
113	            throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "최소 주문 금액에 미달합니다.");
114	        }
115	        if (orderRepository.existsActiveCouponUse(userId, coupon.getCode(), OrderStatus.COUPON_ACTIVE)) {
116	            throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
117	        }
118	        if (coupon.isExhausted()) {
119	            throw new ApiException(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다.");
120	        }
121	    }
122	
123	    @Transactional(readOnly = true)
124	    public OrderResponse get(Long id) {
125	        return orderRepository.findById(id)
126	                .map(OrderResponse::from)
127	                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + id));
128	    }
129	
130	    @Transactional(readOnly = true)
131	    public OrderPageResponse list(String userId, OrderStatus status, int size, String cursor) {
132	        CursorCodec.Cursor decoded = cursor == null ? null : CursorCodec.decode(cursor);
133	
134	        Specification<Order> spec = (root, query, cb) -> cb.conjunction();
135	        if (userId != null) {
136	            spec = spec.and((root, query, cb) -> cb.equal(root.get("userId"), userId));
137	        }
138	        if (status != null) {
139	            spec = spec.and((root, query, cb) -> cb.equal(root.get("status"), status));
140	        }
141	        if (decoded != null) {
142	            spec = spec.and((root, query, cb) -> cb.or(
143	                    cb.lessThan(root.<Instant>get("createdAt"), decoded.createdAt()),
144	                    cb.and(cb.equal(root.<Instant>get("createdAt"), decoded.createdAt()),
145	                            cb.lessThan(root.<Long>get("id"), decoded.id()))));
146	        }
147	        Sort sort = Sort.by(Sort.Order.desc("createdAt"), Sort.Order.desc("id"));
148	        List<Order> fetched = orderRepository.findBy(spec, q -> q.sortBy(sort).limit(size + 1).all());
149	
150	        boolean hasNext = fetched.size() > size;
151	        List<Order> page = hasNext ? fetched.subList(0, size) : fetched;
152	        String nextCursor = null;
153	        if (hasNext) {
154	            Order last = page.get(page.size() - 1);
155	            nextCursor = CursorCodec.encode(last.getCreatedAt(), last.getId());
156	        }
157	        return new OrderPageResponse(page.stream().map(OrderResponse::from).toList(), nextCursor);
158	    }
159	}
