1	package com.example.order.order;
2	
3	import com.example.order.common.error.ApiException;
4	import com.example.order.common.error.ErrorCode;
5	import com.example.order.common.error.InvalidStateException;
6	import com.example.order.common.error.PaymentDeclinedException;
7	import com.example.order.common.time.TimeProvider;
8	import com.example.order.idempotency.IdempotencyService;
9	import com.example.order.idempotency.StoredResponse;
10	import com.example.order.payment.PaymentGatewayClient;
11	import com.example.order.payment.PgPayResult;
12	import java.time.Instant;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	/**
17	 * 결제(R5)·취소/환불(R7)·배송(R8). 한 트랜잭션에서 주문은 1건만 락한다(주문 → 상품 asc → 쿠폰).
18	 */
19	@Service
20	public class OrderLifecycleService {
21	
22	    private final OrderRepository orderRepository;
23	    private final OrderResourceSupport resources;
24	    private final PaymentGatewayClient paymentGateway;
25	    private final IdempotencyService idempotency;
26	    private final TimeProvider time;
27	
28	    public OrderLifecycleService(OrderRepository orderRepository, OrderResourceSupport resources,
29	                                 PaymentGatewayClient paymentGateway, IdempotencyService idempotency,
30	                                 TimeProvider time) {
31	        this.orderRepository = orderRepository;
32	        this.resources = resources;
33	        this.paymentGateway = paymentGateway;
34	        this.idempotency = idempotency;
35	        this.time = time;
36	    }
37	
38	    /** 주문 행 락을 쥔 채 PG를 호출한다(R10.5). */
39	    @Transactional(noRollbackFor = {InvalidStateException.class, PaymentDeclinedException.class})
40	    public StoredResponse pay(long orderId, String cardToken, String idempotencyKey, long idempotencyRecordId) {
41	        Order order = lockOrder(orderId);
42	        Instant now = time.now();
43	        if (order.isExpiredAt(now)) {
44	            resources.releaseReservation(order);
45	            order.expire();
46	            throw new InvalidStateException("결제 가능 시간이 지나 주문이 만료되었습니다: id=" + orderId);
47	        }
48	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT) {
49	            throw new InvalidStateException("결제할 수 없는 주문 상태입니다: " + order.getStatus());
50	        }
51	
52	        String pgPaymentId = null;
53	        if (order.getTotalPrice() > 0) {
54	            PgPayResult result = paymentGateway.pay(idempotencyKey, orderId, order.getTotalPrice(), cardToken);
55	            if (!result.approved()) {
56	                resources.releaseReservation(order);
57	                order.markPaymentFailed(result.paymentId());
58	                throw new PaymentDeclinedException("결제가 거절되었습니다: orderId=" + orderId);
59	            }
60	            pgPaymentId = result.paymentId();
61	        }
62	
63	        resources.commitSale(order);
64	        order.markPaid(time.now(), pgPaymentId);
65	        return idempotency.complete(idempotencyRecordId, 200, OrderResponse.from(order), null);
66	    }
67	
68	    @Transactional(noRollbackFor = InvalidStateException.class)
69	    public OrderResponse cancel(long orderId) {
70	        Order order = lockOrder(orderId);
71	        Instant now = time.now();
72	        if (order.isExpiredAt(now)) {
73	            resources.releaseReservation(order);
74	            order.expire();
75	            throw new InvalidStateException("결제 가능 시간이 지나 주문이 만료되었습니다: id=" + orderId);
76	        }
77	        switch (order.getStatus()) {
78	            case PENDING_PAYMENT -> {
79	                resources.releaseReservation(order);
80	                order.cancel();
81	            }
82	            case PAID -> {
83	                if (order.getPgPaymentId() != null) {
84	                    paymentGateway.refund(order.getPgPaymentId());
85	                }
86	                resources.restock(order);
87	                order.refund();
88	            }
89	            default -> throw new InvalidStateException("취소할 수 없는 주문 상태입니다: " + order.getStatus());
90	        }
91	        return OrderResponse.from(order);
92	    }
93	
94	    @Transactional
95	    public OrderResponse ship(long orderId) {
96	        Order order = lockOrder(orderId);
97	        order.ship();
98	        return OrderResponse.from(order);
99	    }
100	
101	    @Transactional
102	    public OrderResponse deliver(long orderId) {
103	        Order order = lockOrder(orderId);
104	        order.deliver();
105	        return OrderResponse.from(order);
106	    }
107	
108	    private Order lockOrder(long orderId) {
109	        return orderRepository.findByIdForUpdate(orderId)
110	                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + orderId));
111	    }
112	}
