1	package com.example.order.order;
2	
3	import com.example.order.common.error.ApiException;
4	import com.example.order.common.error.ErrorCode;
5	import com.example.order.coupon.Coupon;
6	import com.example.order.coupon.CouponRepository;
7	import com.example.order.product.Product;
8	import com.example.order.product.ProductRepository;
9	import java.util.Collection;
10	import java.util.LinkedHashMap;
11	import java.util.Map;
12	import java.util.TreeSet;
13	import org.springframework.stereotype.Component;
14	
15	/**
16	 * 재고·쿠폰 자원 조작 공통부. 반드시 호출자의 트랜잭션 안에서 사용한다.
17	 * 전역 락 순서(orders → products asc → coupon)를 지키도록 상품은 id 오름차순으로 하나씩 락한다.
18	 */
19	@Component
20	public class OrderResourceSupport {
21	
22	    private final ProductRepository productRepository;
23	    private final CouponRepository couponRepository;
24	
25	    public OrderResourceSupport(ProductRepository productRepository, CouponRepository couponRepository) {
26	        this.productRepository = productRepository;
27	        this.couponRepository = couponRepository;
28	    }
29	
30	    /** id 오름차순으로 FOR UPDATE. 없는 상품이 있으면 404. */
31	    public Map<Long, Product> lockProducts(Collection<Long> productIds) {
32	        Map<Long, Product> locked = new LinkedHashMap<>();
33	        for (Long id : new TreeSet<>(productIds)) {
34	            Product p = productRepository.findByIdForUpdate(id)
35	                    .orElseThrow(() -> new ApiException(ErrorCode.PRODUCT_NOT_FOUND, "상품을 찾을 수 없습니다: id=" + id));
36	            locked.put(id, p);
37	        }
38	        return locked;
39	    }
40	
41	    private Map<Long, Product> lockProductsOf(Order order) {
42	        return lockProducts(order.getItems().stream().map(OrderItem::getProductId).toList());
43	    }
44	
45	    /** 취소·만료·결제 거절: 예약 복원 + 쿠폰 사용 복원. */
46	    public void releaseReservation(Order order) {
47	        Map<Long, Product> products = lockProductsOf(order);
48	        for (OrderItem item : order.getItems()) {
49	            products.get(item.getProductId()).release(item.getQuantity());
50	        }
51	        restoreCoupon(order);
52	    }
53	
54	    /** 결제 승인: stock, reserved 동시 차감. */
55	    public void commitSale(Order order) {
56	        Map<Long, Product> products = lockProductsOf(order);
57	        for (OrderItem item : order.getItems()) {
58	            products.get(item.getProductId()).commitSale(item.getQuantity());
59	        }
60	    }
61	
62	    /** 환불: stock 복원 + 쿠폰 사용 복원. */
63	    public void restock(Order order) {
64	        Map<Long, Product> products = lockProductsOf(order);
65	        for (OrderItem item : order.getItems()) {
66	            products.get(item.getProductId()).restock(item.getQuantity());
67	        }
68	        restoreCoupon(order);
69	    }
70	
71	    public void restoreCoupon(Order order) {
72	        if (order.getCouponCode() == null) {
73	            return;
74	        }
75	        Coupon coupon = couponRepository.findByCodeForUpdate(order.getCouponCode())
76	                .orElseThrow(() -> new ApiException(ErrorCode.COUPON_NOT_FOUND,
77	                        "쿠폰을 찾을 수 없습니다: code=" + order.getCouponCode()));
78	        coupon.restore();
79	    }
80	}
