1	package com.example.order.idempotency;
2	
3	import com.example.order.common.error.ApiException;
4	import com.example.order.common.error.ErrorCode;
5	import com.example.order.common.time.TimeProvider;
6	import com.fasterxml.jackson.core.JsonProcessingException;
7	import com.fasterxml.jackson.databind.ObjectMapper;
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.NoSuchAlgorithmException;
11	import java.util.HexFormat;
12	import java.util.Optional;
13	import java.util.function.LongFunction;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.PlatformTransactionManager;
16	import org.springframework.transaction.annotation.Transactional;
17	import org.springframework.transaction.support.TransactionTemplate;
18	
19	/**
20	 * 멱등 처리(R4). 클레임·해제는 별도 트랜잭션(즉시 커밋), 완료 기록은 호출자(비즈니스) 트랜잭션에 참여한다.
21	 */
22	@Service
23	public class IdempotencyService {
24	
25	    private static final int MAX_CLAIM_ATTEMPTS = 3;
26	
27	    /** 지문 계산 전용(기본 설정). 응답 직렬화용 매퍼와 분리한다. */
28	    private final ObjectMapper fingerprintMapper = new ObjectMapper();
29	    private final ObjectMapper responseMapper;
30	    private final IdempotencyRecordRepository repository;
31	    private final TimeProvider time;
32	    private final TransactionTemplate requiresNew;
33	
34	    public IdempotencyService(ObjectMapper responseMapper, IdempotencyRecordRepository repository,
35	                              TimeProvider time, PlatformTransactionManager txManager) {
36	        this.responseMapper = responseMapper;
37	        this.repository = repository;
38	        this.time = time;
39	        this.requiresNew = new TransactionTemplate(txManager);
40	        this.requiresNew.setPropagationBehavior(TransactionTemplate.PROPAGATION_REQUIRES_NEW);
41	    }
42	
43	    /** SHA-256 hex( userId \n "POST " path \n canonicalBody ). */
44	    public String fingerprint(String userId, String path, Object requestBody) {
45	        String canonical;
46	        try {
47	            canonical = fingerprintMapper.writeValueAsString(requestBody);
48	        } catch (JsonProcessingException e) {
49	            throw new IllegalStateException("요청 본문 직렬화 실패", e);
50	        }
51	        String raw = (userId == null ? "" : userId) + "\n" + "POST " + path + "\n" + canonical;
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
54	            return HexFormat.of().formatHex(digest);
55	        } catch (NoSuchAlgorithmException e) {
56	            throw new IllegalStateException(e);
57	        }
58	    }
59	
60	    /**
61	     * 클레임 후 action을 실행한다. 재생이면 action을 호출하지 않고 저장된 응답을 반환한다.
62	     * action 안에서 예외가 나면 레코드를 삭제하고(R4.4) 예외를 그대로 전파한다.
63	     */
64	    public StoredResponse execute(IdempotencyScope scope, String key, String fingerprint,
65	                                  LongFunction<StoredResponse> action) {
66	        Claim claim = claim(scope, key, fingerprint);
67	        if (claim instanceof Claim.Replay replay) {
68	            return replay.response();
69	        }
70	        long recordId = ((Claim.Owned) claim).recordId();
71	        try {
72	            return action.apply(recordId);
73	        } catch (RuntimeException | Error e) {
74	            try {
75	                release(recordId);
76	            } catch (RuntimeException releaseFailure) {
77	                e.addSuppressed(releaseFailure);
78	            }
79	            throw e;
80	        }
81	    }
82	
83	    /** 비즈니스 트랜잭션 안에서 호출: 응답을 직렬화해 레코드를 COMPLETED로 갱신하고 그 응답을 돌려준다. */
84	    @Transactional
85	    public StoredResponse complete(long recordId, int status, Object body, String location) {
86	        String json;
87	        try {
88	            json = responseMapper.writeValueAsString(body);
89	        } catch (JsonProcessingException e) {
90	            throw new IllegalStateException("응답 직렬화 실패", e);
91	        }
92	        repository.markCompleted(recordId, IdempotencyStatus.COMPLETED, status, json, location, time.now());
93	        return new StoredResponse(status, json, location);
94	    }
95	
96	    private Claim claim(IdempotencyScope scope, String key, String fingerprint) {
97	        for (int attempt = 0; attempt < MAX_CLAIM_ATTEMPTS; attempt++) {
98	            Claim result = requiresNew.execute(status -> tryClaimOnce(scope, key, fingerprint));
99	            if (result != null) {
100	                return result;
101	            }
102	        }
103	        throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "같은 멱등 키의 요청이 처리 중입니다.");
104	    }
105	
106	    /** null이면 소유자가 방금 실패해 레코드가 사라진 것 → 재시도. */
107	    private Claim tryClaimOnce(IdempotencyScope scope, String key, String fingerprint) {
108	        int inserted = repository.tryClaim(scope.name(), key, fingerprint, time.now());
109	        Optional<IdempotencyRecord> existing = repository.findByScopeAndIdemKey(scope, key);
110	        if (existing.isEmpty()) {
111	            return null;
112	        }
113	        IdempotencyRecord record = existing.get();
114	        if (inserted == 1) {
115	            return new Claim.Owned(record.getId());
116	        }
117	        if (!record.getFingerprint().equals(fingerprint)) {
118	            throw new ApiException(ErrorCode.IDEMPOTENCY_KEY_MISMATCH, "같은 멱등 키로 다른 요청이 전달되었습니다.");
119	        }
120	        if (record.getStatus() == IdempotencyStatus.IN_PROGRESS) {
121	            throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "같은 멱등 키의 요청이 처리 중입니다.");
122	        }
123	        return new Claim.Replay(new StoredResponse(
124	                record.getResponseStatus(), record.getResponseBody(), record.getResponseLocation()));
125	    }
126	
127	    private void release(long recordId) {
128	        requiresNew.executeWithoutResult(status ->
129	                repository.releaseInProgress(recordId, IdempotencyStatus.IN_PROGRESS));
130	    }
131	
132	    private sealed interface Claim {
133	        record Owned(long recordId) implements Claim {
134	        }
135	
136	        record Replay(StoredResponse response) implements Claim {
137	        }
138	    }
139	}
