5	import org.slf4j.LoggerFactory;
6	import org.springframework.http.HttpHeaders;
7	import org.springframework.http.HttpStatusCode;
8	import org.springframework.http.MediaType;
9	import org.springframework.http.ProblemDetail;
10	import org.springframework.http.ResponseEntity;
11	import org.springframework.web.bind.annotation.ExceptionHandler;
12	import org.springframework.web.bind.annotation.RestControllerAdvice;
13	import org.springframework.web.context.request.WebRequest;
14	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
15	
16	@RestControllerAdvice
17	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
18	
19	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
20	
21	    @ExceptionHandler(ApiException.class)
22	    public ResponseEntity<ProblemDetail> handleApi(ApiException ex) {
23	        return build(ex.code(), ex.getMessage());
24	    }
25	
26	    @ExceptionHandler(ConstraintViolationException.class)
27	    public ResponseEntity<ProblemDetail> handleConstraintViolation(ConstraintViolationException ex) {
28	        return build(ErrorCode.VALIDATION_ERROR, "요청 검증에 실패했습니다.");
29	    }
30	
31	    @ExceptionHandler(Exception.class)
32	    public ResponseEntity<ProblemDetail> handleUnexpected(Exception ex) {
33	        log.error("Unexpected error", ex);
34	        return build(ErrorCode.INTERNAL_ERROR, "예상치 못한 오류가 발생했습니다.");
35	    }
36	
37	    /** Spring MVC 표준 예외(검증·바인딩·파싱 실패 등)의 400 응답에 code=VALIDATION_ERROR를 부여한다. */
38	    @Override
39	    protected ResponseEntity<Object> handleExceptionInternal(
40	            Exception ex, Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
41	        ResponseEntity<Object> response = super.handleExceptionInternal(ex, body, headers, statusCode, request);
42	        if (response != null && response.getBody() instanceof ProblemDetail pd && statusCode.value() == 400) {
43	            apply(pd, ErrorCode.VALIDATION_ERROR);
44	        }
45	        return response;
46	    }
47	
48	    private static ResponseEntity<ProblemDetail> build(ErrorCode code, String detail) {
49	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(code.status(), detail);
50	        apply(pd, code);
51	        return ResponseEntity.status(code.status())
52	                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
53	                .body(pd);
54	    }
55	
56	    private static void apply(ProblemDetail pd, ErrorCode code) {
57	        pd.setType(java.net.URI.create(code.typeUri()));
58	        pd.setTitle(code.title());
59	        pd.setProperty("code", code.name());
60	    }
61	}
