8	/** 커서 = base64url(no padding) of "{createdAt}|{id}". */
9	public final class CursorCodec {
10	
11	    public record Cursor(Instant createdAt, long id) {
12	    }
13	
14	    private CursorCodec() {
15	    }
16	
17	    public static String encode(Instant createdAt, long id) {
18	        String raw = createdAt.toString() + "|" + id;
19	        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
20	    }
21	
22	    public static Cursor decode(String cursor) {
23	        try {
24	            String raw = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
25	            String[] parts = raw.split("\\|", -1);
26	            if (parts.length != 2) {
27	                throw new InvalidCursorException("해석할 수 없는 cursor 입니다.");
28	            }
29	            return new Cursor(Instant.parse(parts[0]), Long.parseLong(parts[1]));
30	        } catch (IllegalArgumentException | java.time.format.DateTimeParseException e) {
31	            throw new InvalidCursorException("해석할 수 없는 cursor 입니다.");
32	        }
33	    }
