1	package com.example.order.payment;
2	
3	import com.example.order.common.error.PaymentGatewayUnavailableException;
4	import com.fasterxml.jackson.databind.JsonNode;
5	import java.util.LinkedHashMap;
6	import java.util.Map;
7	import org.springframework.http.MediaType;
8	import org.springframework.http.client.SimpleClientHttpRequestFactory;
9	import org.springframework.stereotype.Component;
10	import org.springframework.web.client.RestClient;
11	import org.springframework.web.client.RestClientException;
12	
13	/** 외부 PG 호출. 모든 실패(5xx·4xx·연결 실패·타임아웃·비정상 응답)는 PaymentGatewayUnavailableException. */
14	@Component
15	public class PaymentGatewayClient {
16	
17	    private final RestClient restClient;
18	
19	    public PaymentGatewayClient(PaymentGatewayProperties properties) {
20	        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
21	        factory.setConnectTimeout(properties.connectTimeout());
22	        factory.setReadTimeout(properties.readTimeout());
23	        this.restClient = RestClient.builder()
24	                .baseUrl(properties.url().toString())
25	                .requestFactory(factory)
26	                .build();
27	    }
28	
29	    public PgPayResult pay(String idempotencyKey, long orderId, long amount, String cardToken) {
30	        Map<String, Object> body = new LinkedHashMap<>();
31	        body.put("orderId", orderId);
32	        body.put("amount", amount);
33	        body.put("cardToken", cardToken);
34	        JsonNode node;
35	        try {
36	            node = restClient.post()
37	                    .uri("/v1/payments")
38	                    .header("Idempotency-Key", idempotencyKey)
39	                    .contentType(MediaType.APPLICATION_JSON)
40	                    .body(body)
41	                    .retrieve()
42	                    .body(JsonNode.class);
43	        } catch (RestClientException e) {
44	            throw new PaymentGatewayUnavailableException("PG 결제 요청 실패: " + e.getClass().getSimpleName());
45	        }
46	        String paymentId = textOrNull(node, "paymentId");
47	        String status = textOrNull(node, "status");
48	        if (paymentId == null || status == null) {
49	            throw new PaymentGatewayUnavailableException("PG 응답을 해석할 수 없습니다.");
50	        }
51	        return switch (status) {
52	            case "APPROVED" -> new PgPayResult(paymentId, true);
53	            case "DECLINED" -> new PgPayResult(paymentId, false);
54	            default -> throw new PaymentGatewayUnavailableException("PG 응답 status가 올바르지 않습니다.");
55	        };
56	    }
57	
58	    public PgRefundResult refund(String paymentId) {
59	        JsonNode node;
60	        try {
61	            node = restClient.post()
62	                    .uri("/v1/payments/{paymentId}/refund", paymentId)
63	                    .retrieve()
64	                    .body(JsonNode.class);
65	        } catch (RestClientException e) {
66	            throw new PaymentGatewayUnavailableException("PG 환불 요청 실패: " + e.getClass().getSimpleName());
67	        }
68	        if (!"REFUNDED".equals(textOrNull(node, "status"))) {
69	            throw new PaymentGatewayUnavailableException("PG 환불 응답 status가 올바르지 않습니다.");
70	        }
71	        return new PgRefundResult(paymentId);
72	    }
73	
74	    private static String textOrNull(JsonNode node, String field) {
75	        if (node == null || !node.hasNonNull(field)) {
76	            return null;
77	        }
78	        return node.get(field).asText();
79	    }
80	}
