16	import java.util.concurrent.atomic.AtomicInteger;
17	import java.util.concurrent.atomic.AtomicLong;
18	import java.util.concurrent.atomic.AtomicReference;
19	
20	/**
21	 * 테스트용 가짜 PG 서버(JDK HttpServer, 추가 의존성 없음).
22	 *
23	 * <ul>
24	 *   <li>POST /v1/payments : 헤더 Idempotency-Key, 본문 {orderId, amount, cardToken}</li>
25	 *   <li>POST /v1/payments/{id}/refund</li>
26	 * </ul>
27	 * 응답 모드는 테스트가 {@link #approve()}, {@link #decline()}, {@link #fail5xx()}, {@link #unreachable()} 로 바꾸고,
28	 * {@link #delay(long)} 로 응답 지연(ms)을 추가한다(모드와 독립). 지연은 모드 처리 전에 적용된다.
29	 * 같은 Idempotency-Key 결제 요청은 최초 결과(승인/거절)를 그대로 돌려준다(PG 계약).
30	 * 5xx 응답은 "결과"가 아니므로 저장하지 않는다. 모든 필드는 스레드 안전하다.
31	 */
32	public class FakePaymentGateway {
33	
34	    public enum Mode { APPROVED, DECLINED, ERROR_5XX }
35	
36	    /** 수신한 요청 기록. headers 키는 소문자. */
37	    public record RecordedRequest(String method, String path, Map<String, String> headers, String body) {
38	        public String idempotencyKey() {
39	            return headers.get("idempotency-key");
40	        }
41	    }
42	
43	    private final AtomicReference<Mode> mode = new AtomicReference<>(Mode.APPROVED);
44	    private final AtomicLong delayMillis = new AtomicLong(0);
45	    private final AtomicInteger payCalls = new AtomicInteger();
46	    private final AtomicInteger refundCalls = new AtomicInteger();
47	    private final AtomicLong paymentSeq = new AtomicLong();
48	    private final List<RecordedRequest> requests = new CopyOnWriteArrayList<>();
49	    /** Idempotency-Key -> 최초 결제 응답 본문 */
50	    private final Map<String, String> paymentsByKey = new ConcurrentHashMap<>();
51	
52	    private volatile HttpServer server;
53	    private volatile ExecutorService executor;
54	    private volatile int port;
55	
56	    public synchronized void start() {
57	        try {
58	            bind(0);
59	        } catch (IOException e) {
60	            throw new IllegalStateException("가짜 PG 서버를 시작하지 못했습니다.", e);
61	        }
62	    }
63	
64	    public synchronized void stop() {
65	        shutdown();
66	    }
67	
68	    public String url() {
69	        return "http://localhost:" + port;
70	    }
71	
72	    public int port() {
73	        return port;
74	    }
75	
76	    // ---- 모드 전환 ----
77	
78	    public FakePaymentGateway approve() {
79	        return mode(Mode.APPROVED);
80	    }
81	
82	    public FakePaymentGateway decline() {
83	        return mode(Mode.DECLINED);
84	    }
85	
86	    public FakePaymentGateway fail5xx() {
87	        return mode(Mode.ERROR_5XX);
88	    }
89	
90	    private FakePaymentGateway mode(Mode m) {
91	        restoreIfStopped();
92	        mode.set(m);
93	        return this;
94	    }
95	
96	    /** 응답 전 지연(ms). 0이면 지연 없음. */
97	    public FakePaymentGateway delay(long millis) {
98	        delayMillis.set(millis);
99	        return this;
100	    }
101	
102	    /** 연결 불가: 리스너를 닫아 연결 거부(Connection refused)를 유발한다. approve()/decline()/fail5xx() 로 복구. */
103	    public synchronized FakePaymentGateway unreachable() {
104	        shutdown();
105	        return this;
106	    }
107	
108	    private synchronized void restoreIfStopped() {
109	        if (server == null) {
110	            try {
111	                bind(port);
112	            } catch (IOException e) {
113	                throw new IllegalStateException("가짜 PG 서버를 같은 포트로 재시작하지 못했습니다.", e);
114	            }
115	        }
116	    }
117	
118	    /** 모드 APPROVED, 지연 0, 기록 전부 초기화. 중단된 서버는 같은 포트로 재시작한다. */
119	    public synchronized void reset() {
120	        restoreIfStopped();
121	        mode.set(Mode.APPROVED);
122	        delayMillis.set(0);
123	        payCalls.set(0);
124	        refundCalls.set(0);
125	        paymentSeq.set(0);
126	        requests.clear();
127	        paymentsByKey.clear();
128	    }
129	
130	    // ---- 기록 조회 ----
131	
132	    public int payCallCount() {
133	        return payCalls.get();
134	    }
135	
136	    public int refundCallCount() {
137	        return refundCalls.get();
138	    }
139	
140	    public List<RecordedRequest> requests() {
141	        return List.copyOf(requests);
142	    }
143	
144	    public RecordedRequest lastPayRequest() {
145	        return lastMatching("/v1/payments");
146	    }
147	
148	    public RecordedRequest lastRefundRequest() {
149	        RecordedRequest last = null;
150	        for (RecordedRequest r : requests) {
151	            if (r.path().endsWith("/refund")) {
152	                last = r;
153	            }
154	        }
155	        return last;
156	    }
157	
158	    private RecordedRequest lastMatching(String exactPath) {
159	        RecordedRequest last = null;
160	        for (RecordedRequest r : requests) {
161	            if (r.path().equals(exactPath)) {
162	                last = r;
163	            }
164	        }
165	        return last;
166	    }
167	
168	    /** 서로 다른 Idempotency-Key 로 실제 처리된 결제 건수. */
169	    public int distinctPaymentCount() {
170	        return paymentsByKey.size();
171	    }
172	
173	    // ---- 내부 ----
174	
175	    private void bind(int bindPort) throws IOException {
176	        HttpServer s = HttpServer.create(new InetSocketAddress("localhost", bindPort), 128);
177	        ExecutorService ex = Executors.newCachedThreadPool(r -> {
178	            Thread t = new Thread(r, "fake-pg");
179	            t.setDaemon(true);
180	            return t;
181	        });
182	        s.setExecutor(ex);
183	        s.createContext("/v1/payments", new PaymentsHandler());
184	        s.start();
185	        this.server = s;
186	        this.executor = ex;
187	        this.port = s.getAddress().getPort();
188	    }
189	
190	    private void shutdown() {
191	        HttpServer s = this.server;
192	        ExecutorService ex = this.executor;
193	        this.server = null;
194	        this.executor = null;
195	        if (s != null) {
196	            s.stop(0);
197	        }
198	        if (ex != null) {
199	            ex.shutdownNow();
200	        }
201	    }
202	
203	    private class PaymentsHandler implements HttpHandler {
204	        @Override
205	        public void handle(HttpExchange exchange) throws IOException {
206	            try (exchange) {
207	                String path = exchange.getRequestURI().getPath();
208	                String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
209	                Map<String, String> headers = new ConcurrentHashMap<>();
210	                exchange.getRequestHeaders().forEach((k, v) -> {
211	                    if (!v.isEmpty()) {
212	                        headers.put(k.toLowerCase(), v.get(0));
213	                    }
214	                });
215	                boolean refund = path.endsWith("/refund");
216	                if (refund) {
217	                    refundCalls.incrementAndGet();
218	                } else {
219	                    payCalls.incrementAndGet();
220	                }
221	                requests.add(new RecordedRequest(exchange.getRequestMethod(), path, headers, body));
222	
223	                long delay = delayMillis.get();
224	                if (delay > 0) {
225	                    try {
226	                        Thread.sleep(delay);
227	                    } catch (InterruptedException e) {
228	                        Thread.currentThread().interrupt();
229	                        return;
230	                    }
231	                }
232	
233	                if (!"POST".equals(exchange.getRequestMethod())) {
234	                    respond(exchange, 405, "{}");
235	                    return;
236	                }
237	                Mode m = mode.get();
238	                if (m == Mode.ERROR_5XX) {
239	                    respond(exchange, 500, "{\"error\":\"pg down\"}");
240	                    return;
241	                }
242	                if (refund) {
243	                    String paymentId = path.substring("/v1/payments/".length(), path.length() - "/refund".length());
244	                    respond(exchange, 200, "{\"paymentId\":\"" + paymentId + "\",\"status\":\"REFUNDED\"}");
245	                    return;
246	                }
247	                String key = headers.getOrDefault("idempotency-key", "");
248	                String result = paymentsByKey.computeIfAbsent(key, k -> {
249	                    String status = m == Mode.DECLINED ? "DECLINED" : "APPROVED";
250	                    return "{\"paymentId\":\"pay_" + paymentSeq.incrementAndGet() + "\",\"status\":\"" + status + "\"}";
251	                });
252	                respond(exchange, 200, result);
253	            }
254	        }
255	
256	        private void respond(HttpExchange exchange, int status, String json) throws IOException {
257	            byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
258	            exchange.getResponseHeaders().set("Content-Type", "application/json");
259	            exchange.sendResponseHeaders(status, bytes.length);
260	            try (OutputStream os = exchange.getResponseBody()) {
261	                os.write(bytes);
262	            }
263	        }
264	    }
265	}
