package com.example.order.support;

import com.fasterxml.jackson.databind.JsonNode;
import java.util.Map;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.TestPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;

/**
 * 통합 테스트 공통 베이스.
 *
 * <ul>
 *   <li>PostgreSQL 컨테이너와 가짜 PG 서버는 JVM 당 싱글턴(컨텍스트 캐시 유지).</li>
 *   <li>{@code payment.gateway.url} 은 가짜 PG, {@code order.payment-ttl} 은 기본 PT15M(클래스 레벨
 *       {@code @TestPropertySource(properties = "order.payment-ttl=PT3S")} 로 서브클래스에서 덮어쓸 수 있다 —
 *       다른 컨텍스트가 하나 더 만들어질 뿐 컨테이너·가짜 PG는 공유).</li>
 *   <li>매 테스트 전에 모든 테이블 TRUNCATE + 가짜 PG reset.</li>
 * </ul>
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@TestPropertySource(properties = "order.payment-ttl=PT15M")
public abstract class IntegrationTestBase {

    @ServiceConnection
    protected static final PostgreSQLContainer<?> POSTGRES = new PostgreSQLContainer<>("postgres:16-alpine");

    protected static final FakePaymentGateway PG = new FakePaymentGateway();

    static {
        POSTGRES.start();
        PG.start();
        Runtime.getRuntime().addShutdownHook(new Thread(PG::stop));
    }

    @DynamicPropertySource
    static void dynamicProperties(DynamicPropertyRegistry registry) {
        registry.add("payment.gateway.url", PG::url);
    }

    @Autowired
    protected TestRestTemplate rest;

    @Autowired
    protected JdbcTemplate jdbc;

    @BeforeEach
    void resetState() {
        jdbc.execute("TRUNCATE order_items, orders, idempotency_records, coupons, products RESTART IDENTITY CASCADE");
        PG.reset();
    }

    // ---- HTTP 헬퍼 (응답 본문은 JsonNode; 오류 응답도 예외 없이 반환) ----

    /** headers 는 name, value, name, value ... 순서. */
    protected ResponseEntity<JsonNode> post(String path, Object body, String... headers) {
        return exchange(HttpMethod.POST, path, body, headers);
    }

    protected ResponseEntity<JsonNode> get(String path) {
        return exchange(HttpMethod.GET, path, null);
    }

    protected ResponseEntity<JsonNode> exchange(HttpMethod method, String path, Object body, String... headers) {
        HttpHeaders h = new HttpHeaders();
        h.setContentType(MediaType.APPLICATION_JSON);
        for (int i = 0; i + 1 < headers.length; i += 2) {
            h.set(headers[i], headers[i + 1]);
        }
        return rest.exchange(path, method, new HttpEntity<>(body, h), JsonNode.class);
    }

    // ---- 도메인 헬퍼 ----

    protected JsonNode createProduct(String name, long price, int stock) {
        ResponseEntity<JsonNode> res = post("/api/products", Map.of("name", name, "price", price, "stock", stock));
        if (res.getStatusCode().value() != 201) {
            throw new AssertionError("상품 생성 실패: " + res.getStatusCode() + " " + res.getBody());
        }
        return res.getBody();
    }

    protected ResponseEntity<JsonNode> createOrder(String userId, String idempotencyKey, Object body) {
        return post("/api/orders", body, "X-User-Id", userId, "Idempotency-Key", idempotencyKey);
    }

    protected ResponseEntity<JsonNode> payOrder(long orderId, String idempotencyKey, String cardToken) {
        return post("/api/orders/" + orderId + "/pay", Map.of("cardToken", cardToken),
                "Idempotency-Key", idempotencyKey);
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.IntegrationTestBase;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

class OrderPaymentSmokeTest extends IntegrationTestBase {

    @Test
    void createOrderThenPay_approved() {
        JsonNode product = createProduct("키보드", 15000, 10);
        long productId = product.get("id").asLong();

        ResponseEntity<JsonNode> order = createOrder("user-1", "order-key-1",
                Map.of("items", List.of(Map.of("productId", productId, "quantity", 2))));

        assertThat(order.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(order.getHeaders().getLocation()).isNotNull();
        assertThat(order.getBody().get("status").asText()).isEqualTo("PENDING_PAYMENT");
        assertThat(order.getBody().get("totalPrice").asLong()).isEqualTo(30000);
        assertThat(get("/api/products/" + productId).getBody().get("reserved").asInt()).isEqualTo(2);

        long orderId = order.getBody().get("id").asLong();
        ResponseEntity<JsonNode> paid = payOrder(orderId, "pay-key-1", "tok_visa");

        assertThat(paid.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(paid.getBody().get("status").asText()).isEqualTo("PAID");
        assertThat(paid.getBody().get("paidAt").isNull()).isFalse();
        assertThat(PG.payCallCount()).isEqualTo(1);
        assertThat(PG.lastPayRequest().idempotencyKey()).isEqualTo("pay-key-1");
        assertThat(PG.lastPayRequest().body()).contains("tok_visa").contains("30000");

        JsonNode after = get("/api/products/" + productId).getBody();
        assertThat(after.get("stock").asInt()).isEqualTo(8);
        assertThat(after.get("reserved").asInt()).isZero();
    }

    @Test
    void pay_declined_returns402_andRestoresReservation() {
        long productId = createProduct("마우스", 5000, 3).get("id").asLong();
        long orderId = createOrder("user-1", "order-key-2",
                Map.of("items", List.of(Map.of("productId", productId, "quantity", 1)))).getBody().get("id").asLong();
        PG.decline();

        ResponseEntity<JsonNode> res = payOrder(orderId, "pay-key-2", "tok_declined");

        assertThat(res.getStatusCode()).isEqualTo(HttpStatus.PAYMENT_REQUIRED);
        assertThat(res.getBody().get("code").asText()).isEqualTo("PAYMENT_DECLINED");
        assertThat(get("/api/orders/" + orderId).getBody().get("status").asText()).isEqualTo("PAYMENT_FAILED");
        assertThat(get("/api/products/" + productId).getBody().get("reserved").asInt()).isZero();
    }

    @Test
    void createOrder_sameKeyReplaysFirstResponse() {
        long productId = createProduct("모니터", 100000, 5).get("id").asLong();
        Map<String, Object> body = Map.of("items", List.of(Map.of("productId", productId, "quantity", 1)));

        ResponseEntity<JsonNode> first = createOrder("user-1", "same-key", body);
        ResponseEntity<JsonNode> second = createOrder("user-1", "same-key", body);

        assertThat(second.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(second.getBody().get("id").asLong()).isEqualTo(first.getBody().get("id").asLong());
        assertThat(get("/api/products/" + productId).getBody().get("reserved").asInt()).isEqualTo(1);
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.IntegrationTestBase;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;

class ProductSmokeTest extends IntegrationTestBase {

    @Test
    void createAndGetProduct() {
        ResponseEntity<JsonNode> created = post("/api/products", Map.of("name", "키보드", "price", 15000, "stock", 10));

        assertThat(created.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(created.getHeaders().getLocation()).isNotNull();
        assertThat(created.getBody().get("reserved").asInt()).isZero();
        assertThat(created.getBody().get("available").asInt()).isEqualTo(10);

        ResponseEntity<JsonNode> fetched = get(created.getHeaders().getLocation().toString());
        assertThat(fetched.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(fetched.getBody().get("name").asText()).isEqualTo("키보드");
        assertThat(fetched.getBody().get("price").asLong()).isEqualTo(15000);
    }

    @Test
    void invalidProductReturnsProblemDetail400() {
        ResponseEntity<JsonNode> res = post("/api/products", Map.of("name", " ", "price", 0, "stock", -1));

        assertThat(res.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(res.getHeaders().getContentType()).isEqualTo(MediaType.APPLICATION_PROBLEM_JSON);
        assertThat(res.getBody().get("code").asText()).isEqualTo("VALIDATION_ERROR");
    }

    @Test
    void unknownProductReturns404() {
        ResponseEntity<JsonNode> res = get("/api/products/999");

        assertThat(res.getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);
        assertThat(res.getBody().get("code").asText()).isEqualTo("PRODUCT_NOT_FOUND");
    }
}

package com.example.order.order;

import com.example.order.idempotency.IdempotencyScope;
import com.example.order.idempotency.IdempotencyService;
import com.example.order.idempotency.StoredResponse;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService orderService;
    private final OrderLifecycleService lifecycleService;
    private final IdempotencyService idempotency;

    public OrderController(OrderService orderService, OrderLifecycleService lifecycleService,
                           IdempotencyService idempotency) {
        this.orderService = orderService;
        this.lifecycleService = lifecycleService;
        this.idempotency = idempotency;
    }

    @PostMapping
    public ResponseEntity<String> create(
            @RequestHeader("X-User-Id") @NotBlank @Size(max = 50) String userId,
            @RequestHeader("Idempotency-Key") @Size(min = 1, max = 64) String idempotencyKey,
            @Valid @RequestBody CreateOrderRequest request) {
        String fingerprint = idempotency.fingerprint(userId, "/api/orders", request);
        StoredResponse stored = idempotency.execute(IdempotencyScope.CREATE_ORDER, idempotencyKey, fingerprint,
                recordId -> orderService.create(userId, request, recordId));
        return toResponse(stored);
    }

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable Long id) {
        return orderService.get(id);
    }

    @GetMapping
    public OrderPageResponse list(
            @RequestParam(required = false) String userId,
            @RequestParam(required = false) OrderStatus status,
            @RequestParam(defaultValue = "20") @Min(1) @Max(100) int size,
            @RequestParam(required = false) String cursor) {
        return orderService.list(userId, status, size, cursor);
    }

    @PostMapping("/{id}/pay")
    public ResponseEntity<String> pay(
            @PathVariable Long id,
            @RequestHeader("Idempotency-Key") @Size(min = 1, max = 64) String idempotencyKey,
            @RequestHeader(value = "X-User-Id", required = false) String userId,
            @Valid @RequestBody PayRequest request) {
        String fingerprint = idempotency.fingerprint(userId, "/api/orders/" + id + "/pay", request);
        StoredResponse stored = idempotency.execute(IdempotencyScope.PAY_ORDER, idempotencyKey, fingerprint,
                recordId -> lifecycleService.pay(id, request.cardToken(), idempotencyKey, recordId));
        return toResponse(stored);
    }

    @PostMapping("/{id}/cancel")
    public OrderResponse cancel(@PathVariable Long id) {
        return lifecycleService.cancel(id);
    }

    @PostMapping("/{id}/ship")
    public OrderResponse ship(@PathVariable Long id) {
        return lifecycleService.ship(id);
    }

    @PostMapping("/{id}/deliver")
    public OrderResponse deliver(@PathVariable Long id) {
        return lifecycleService.deliver(id);
    }

    private static ResponseEntity<String> toResponse(StoredResponse stored) {
        ResponseEntity.BodyBuilder builder = ResponseEntity.status(HttpStatus.valueOf(stored.status()))
                .contentType(MediaType.APPLICATION_JSON);
        if (stored.location() != null) {
            builder.header(HttpHeaders.LOCATION, stored.location());
        }
        return builder.body(stored.body());
    }
}
