import com.example.order.common.time.TimeProvider;
import com.example.order.coupon.Coupon;
import com.example.order.coupon.CouponPolicy;
import com.example.order.coupon.CouponRepository;
import com.example.order.idempotency.IdempotencyService;
import com.example.order.idempotency.StoredResponse;
import com.example.order.product.Product;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.data.domain.Sort;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** 주문 생성(R3)·조회·목록(R9). */
@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final CouponRepository couponRepository;
    private final OrderResourceSupport resources;
    private final IdempotencyService idempotency;
    private final TimeProvider time;
    private final OrderProperties properties;

    public OrderService(OrderRepository orderRepository, CouponRepository couponRepository,
                        OrderResourceSupport resources, IdempotencyService idempotency,
                        TimeProvider time, OrderProperties properties) {
        this.orderRepository = orderRepository;
        this.couponRepository = couponRepository;
        this.resources = resources;
        this.idempotency = idempotency;
        this.time = time;
        this.properties = properties;
    }

    @Transactional
    public StoredResponse create(String userId, CreateOrderRequest request, long idempotencyRecordId) {
        Instant now = time.now();
        List<CreateOrderRequest.Item> items = request.items();

        // 4. 상품 락(id 오름차순) — 없으면 404
        Map<Long, Product> products = resources.lockProducts(items.stream().map(CreateOrderRequest.Item::productId).toList());

        // 5. 쿠폰 락 — 없으면 404
        Coupon coupon = null;
        if (request.couponCode() != null) {
            coupon = couponRepository.findByCodeForUpdate(request.couponCode())
                    .orElseThrow(() -> new ApiException(ErrorCode.COUPON_NOT_FOUND,
                            "쿠폰을 찾을 수 없습니다: code=" + request.couponCode()));
        }

        // 6. 재고 검사 (요청 항목 순서)
        for (CreateOrderRequest.Item item : items) {
            Product p = products.get(item.productId());
            if (p.available() < item.quantity()) {
                throw new ApiException(ErrorCode.INSUFFICIENT_STOCK, "상품 " + p.getId() + "의 가용 재고("
                        + p.available() + ")가 요청 수량(" + item.quantity() + ")보다 적습니다.");
            }
        }

        // 7. 소계
        long subtotal = 0;
        for (CreateOrderRequest.Item item : items) {
            subtotal = Math.addExact(subtotal,
                    Math.multiplyExact(products.get(item.productId()).getPrice(), (long) item.quantity()));
        }

        // 8. 쿠폰 판정
        long discount = 0;
        if (coupon != null) {
            checkCouponApplicable(coupon, userId, subtotal, now);
            discount = CouponPolicy.discount(coupon, subtotal);
        }

        // 9. 반영
        for (CreateOrderRequest.Item item : items) {
            products.get(item.productId()).reserve(item.quantity());
        }
        if (coupon != null) {
            coupon.use();
        }
        Order order = Order.create(userId, coupon == null ? null : coupon.getCode(), subtotal, discount,
                now, now.plus(properties.paymentTtl()).truncatedTo(ChronoUnit.MICROS));
        for (int i = 0; i < items.size(); i++) {
            CreateOrderRequest.Item item = items.get(i);
            order.addItem(i, item.productId(), item.quantity(), products.get(item.productId()).getPrice());
        }
        try {
            orderRepository.saveAndFlush(order);
        } catch (DataIntegrityViolationException e) {
            if (String.valueOf(e.getMessage()).contains("ux_orders_user_coupon_active")) {
                throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
            }
            throw e;
        }

        // 10. 멱등 레코드 완료 (같은 트랜잭션)
        return idempotency.complete(idempotencyRecordId, 201, OrderResponse.from(order), "/api/orders/" + order.getId());
    }

    private void checkCouponApplicable(Coupon coupon, String userId, long subtotal, Instant now) {
        if (!coupon.isWithinPeriod(now)) {
            throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "쿠폰 사용 가능 기간이 아닙니다.");
        }
        if (subtotal < coupon.getMinOrderAmount()) {
            throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "최소 주문 금액에 미달합니다.");
        }
        if (orderRepository.existsActiveCouponUse(userId, coupon.getCode(), OrderStatus.COUPON_ACTIVE)) {
            throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다.");
        }
        if (coupon.isExhausted()) {
            throw new ApiException(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다.");
        }
    }

    @Transactional(readOnly = true)
    public OrderResponse get(Long id) {
        return orderRepository.findById(id)
                .map(OrderResponse::from)
                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + id));
    }

    @Transactional(readOnly = true)
    public OrderPageResponse list(String userId, OrderStatus status, int size, String cursor) {
        CursorCodec.Cursor decoded = cursor == null ? null : CursorCodec.decode(cursor);

        Specification<Order> spec = (root, query, cb) -> cb.conjunction();
        if (userId != null) {
            spec = spec.and((root, query, cb) -> cb.equal(root.get("userId"), userId));
        }
        if (status != null) {
            spec = spec.and((root, query, cb) -> cb.equal(root.get("status"), status));
        }
        if (decoded != null) {
            spec = spec.and((root, query, cb) -> cb.or(
                    cb.lessThan(root.<Instant>get("createdAt"), decoded.createdAt()),
                    cb.and(cb.equal(root.<Instant>get("createdAt"), decoded.createdAt()),
                            cb.lessThan(root.<Long>get("id"), decoded.id()))));
        }
        Sort sort = Sort.by(Sort.Order.desc("createdAt"), Sort.Order.desc("id"));
        List<Order> fetched = orderRepository.findBy(spec, q -> q.sortBy(sort).limit(size + 1).all());

        boolean hasNext = fetched.size() > size;
        List<Order> page = hasNext ? fetched.subList(0, size) : fetched;
        String nextCursor = null;
        if (hasNext) {
            Order last = page.get(page.size() - 1);
            nextCursor = CursorCodec.encode(last.getCreatedAt(), last.getId());
        }
        return new OrderPageResponse(page.stream().map(OrderResponse::from).toList(), nextCursor);
    }
}
package com.example.order.order;

import com.example.order.common.error.ApiException;
import com.example.order.common.error.ErrorCode;
import com.example.order.common.error.InvalidStateException;
import com.example.order.common.error.PaymentDeclinedException;
import com.example.order.common.time.TimeProvider;
import com.example.order.idempotency.IdempotencyService;
import com.example.order.idempotency.StoredResponse;
import com.example.order.payment.PaymentGatewayClient;
import com.example.order.payment.PgPayResult;
import java.time.Instant;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 결제(R5)·취소/환불(R7)·배송(R8). 한 트랜잭션에서 주문은 1건만 락한다(주문 → 상품 asc → 쿠폰).
 */
@Service
public class OrderLifecycleService {

    private final OrderRepository orderRepository;
    private final OrderResourceSupport resources;
    private final PaymentGatewayClient paymentGateway;
    private final IdempotencyService idempotency;
    private final TimeProvider time;

    public OrderLifecycleService(OrderRepository orderRepository, OrderResourceSupport resources,
                                 PaymentGatewayClient paymentGateway, IdempotencyService idempotency,
                                 TimeProvider time) {
        this.orderRepository = orderRepository;
        this.resources = resources;
        this.paymentGateway = paymentGateway;
        this.idempotency = idempotency;
        this.time = time;
    }

    /** 주문 행 락을 쥔 채 PG를 호출한다(R10.5). */
    @Transactional(noRollbackFor = {InvalidStateException.class, PaymentDeclinedException.class})
    public StoredResponse pay(long orderId, String cardToken, String idempotencyKey, long idempotencyRecordId) {
        Order order = lockOrder(orderId);
        Instant now = time.now();
        if (order.isExpiredAt(now)) {
            resources.releaseReservation(order);
            order.expire();
            throw new InvalidStateException("결제 가능 시간이 지나 주문이 만료되었습니다: id=" + orderId);
        }
        if (order.getStatus() != OrderStatus.PENDING_PAYMENT) {
            throw new InvalidStateException("결제할 수 없는 주문 상태입니다: " + order.getStatus());
        }

        String pgPaymentId = null;
        if (order.getTotalPrice() > 0) {
            PgPayResult result = paymentGateway.pay(idempotencyKey, orderId, order.getTotalPrice(), cardToken);
            if (!result.approved()) {
                resources.releaseReservation(order);
                order.markPaymentFailed(result.paymentId());
                throw new PaymentDeclinedException("결제가 거절되었습니다: orderId=" + orderId);
            }
            pgPaymentId = result.paymentId();
        }

        resources.commitSale(order);
        order.markPaid(time.now(), pgPaymentId);
        return idempotency.complete(idempotencyRecordId, 200, OrderResponse.from(order), null);
    }

    @Transactional(noRollbackFor = InvalidStateException.class)
    public OrderResponse cancel(long orderId) {
        Order order = lockOrder(orderId);
        Instant now = time.now();
        if (order.isExpiredAt(now)) {
            resources.releaseReservation(order);
            order.expire();
            throw new InvalidStateException("결제 가능 시간이 지나 주문이 만료되었습니다: id=" + orderId);
        }
        switch (order.getStatus()) {
            case PENDING_PAYMENT -> {
                resources.releaseReservation(order);
                order.cancel();
            }
            case PAID -> {
                if (order.getPgPaymentId() != null) {
                    paymentGateway.refund(order.getPgPaymentId());
                }
                resources.restock(order);
                order.refund();
            }
            default -> throw new InvalidStateException("취소할 수 없는 주문 상태입니다: " + order.getStatus());
        }
        return OrderResponse.from(order);
    }

    @Transactional
    public OrderResponse ship(long orderId) {
        Order order = lockOrder(orderId);
        order.ship();
        return OrderResponse.from(order);
    }

    @Transactional
    public OrderResponse deliver(long orderId) {
        Order order = lockOrder(orderId);
        order.deliver();
        return OrderResponse.from(order);
    }

    private Order lockOrder(long orderId) {
        return orderRepository.findByIdForUpdate(orderId)
                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "주문을 찾을 수 없습니다: id=" + orderId));
    }
}
package com.example.order.idempotency;

import com.example.order.common.error.ApiException;
import com.example.order.common.error.ErrorCode;
import com.example.order.common.time.TimeProvider;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Optional;
import java.util.function.LongFunction;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * 멱등 처리(R4). 클레임·해제는 별도 트랜잭션(즉시 커밋), 완료 기록은 호출자(비즈니스) 트랜잭션에 참여한다.
 */
@Service
public class IdempotencyService {

    private static final int MAX_CLAIM_ATTEMPTS = 3;

    /** 지문 계산 전용(기본 설정). 응답 직렬화용 매퍼와 분리한다. */
    private final ObjectMapper fingerprintMapper = new ObjectMapper();
    private final ObjectMapper responseMapper;
    private final IdempotencyRecordRepository repository;
    private final TimeProvider time;
    private final TransactionTemplate requiresNew;

    public IdempotencyService(ObjectMapper responseMapper, IdempotencyRecordRepository repository,
                              TimeProvider time, PlatformTransactionManager txManager) {
        this.responseMapper = responseMapper;
        this.repository = repository;
        this.time = time;
        this.requiresNew = new TransactionTemplate(txManager);
        this.requiresNew.setPropagationBehavior(TransactionTemplate.PROPAGATION_REQUIRES_NEW);
    }

    /** SHA-256 hex( userId \n "POST " path \n canonicalBody ). */
    public String fingerprint(String userId, String path, Object requestBody) {
        String canonical;
        try {
            canonical = fingerprintMapper.writeValueAsString(requestBody);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("요청 본문 직렬화 실패", e);
        }
        String raw = (userId == null ? "" : userId) + "\n" + "POST " + path + "\n" + canonical;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /**
     * 클레임 후 action을 실행한다. 재생이면 action을 호출하지 않고 저장된 응답을 반환한다.
     * action 안에서 예외가 나면 레코드를 삭제하고(R4.4) 예외를 그대로 전파한다.
     */
    public StoredResponse execute(IdempotencyScope scope, String key, String fingerprint,
                                  LongFunction<StoredResponse> action) {
        Claim claim = claim(scope, key, fingerprint);
        if (claim instanceof Claim.Replay replay) {
            return replay.response();
        }
        long recordId = ((Claim.Owned) claim).recordId();
        try {
            return action.apply(recordId);
        } catch (RuntimeException | Error e) {
            try {
                release(recordId);
            } catch (RuntimeException releaseFailure) {
                e.addSuppressed(releaseFailure);
            }
            throw e;
        }
    }

    /** 비즈니스 트랜잭션 안에서 호출: 응답을 직렬화해 레코드를 COMPLETED로 갱신하고 그 응답을 돌려준다. */
    @Transactional
    public StoredResponse complete(long recordId, int status, Object body, String location) {
        String json;
        try {
            json = responseMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("응답 직렬화 실패", e);
        }
        repository.markCompleted(recordId, IdempotencyStatus.COMPLETED, status, json, location, time.now());
        return new StoredResponse(status, json, location);
    }

    private Claim claim(IdempotencyScope scope, String key, String fingerprint) {
        for (int attempt = 0; attempt < MAX_CLAIM_ATTEMPTS; attempt++) {
            Claim result = requiresNew.execute(status -> tryClaimOnce(scope, key, fingerprint));
            if (result != null) {
                return result;
            }
        }
        throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "같은 멱등 키의 요청이 처리 중입니다.");
    }

    /** null이면 소유자가 방금 실패해 레코드가 사라진 것 → 재시도. */
    private Claim tryClaimOnce(IdempotencyScope scope, String key, String fingerprint) {
        int inserted = repository.tryClaim(scope.name(), key, fingerprint, time.now());
        Optional<IdempotencyRecord> existing = repository.findByScopeAndIdemKey(scope, key);
        if (existing.isEmpty()) {
            return null;
        }
        IdempotencyRecord record = existing.get();
        if (inserted == 1) {
            return new Claim.Owned(record.getId());
        }
        if (!record.getFingerprint().equals(fingerprint)) {
            throw new ApiException(ErrorCode.IDEMPOTENCY_KEY_MISMATCH, "같은 멱등 키로 다른 요청이 전달되었습니다.");
        }
        if (record.getStatus() == IdempotencyStatus.IN_PROGRESS) {
            throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "같은 멱등 키의 요청이 처리 중입니다.");
        }
        return new Claim.Replay(new StoredResponse(
                record.getResponseStatus(), record.getResponseBody(), record.getResponseLocation()));
    }

    private void release(long recordId) {
        requiresNew.executeWithoutResult(status ->
                repository.releaseInProgress(recordId, IdempotencyStatus.IN_PROGRESS));
    }

    private sealed interface Claim {
        record Owned(long recordId) implements Claim {
        }

        record Replay(StoredResponse response) implements Claim {
        }
    }
}

        }
    }

    private final AtomicReference<Mode> mode = new AtomicReference<>(Mode.APPROVED);
    private final AtomicLong delayMillis = new AtomicLong(0);
    private final AtomicInteger payCalls = new AtomicInteger();
    private final AtomicInteger refundCalls = new AtomicInteger();
    private final AtomicLong paymentSeq = new AtomicLong();
    private final List<RecordedRequest> requests = new CopyOnWriteArrayList<>();
    /** Idempotency-Key -> 최초 결제 응답 본문 */
    private final Map<String, String> paymentsByKey = new ConcurrentHashMap<>();

    private volatile HttpServer server;
    private volatile ExecutorService executor;
    private volatile int port;

    public synchronized void start() {
        try {
            bind(0);
        } catch (IOException e) {
            throw new IllegalStateException("가짜 PG 서버를 시작하지 못했습니다.", e);
        }
    }

    public synchronized void stop() {
        shutdown();
    }

    public String url() {
        return "http://localhost:" + port;
    }

    public int port() {
        return port;
    }

    // ---- 모드 전환 ----

    public FakePaymentGateway approve() {
        return mode(Mode.APPROVED);
    }

    public FakePaymentGateway decline() {
        return mode(Mode.DECLINED);
    }

    public FakePaymentGateway fail5xx() {
        return mode(Mode.ERROR_5XX);
    }

    private FakePaymentGateway mode(Mode m) {
        restoreIfStopped();
        mode.set(m);
        return this;
    }

    /** 응답 전 지연(ms). 0이면 지연 없음. */
    public FakePaymentGateway delay(long millis) {
        delayMillis.set(millis);
        return this;
    }

    /** 연결 불가: 리스너를 닫아 연결 거부(Connection refused)를 유발한다. approve()/decline()/fail5xx() 로 복구. */
    public synchronized FakePaymentGateway unreachable() {
        shutdown();
        return this;
    }

    private synchronized void restoreIfStopped() {
        if (server == null) {
            try {
                bind(port);
            } catch (IOException e) {
                throw new IllegalStateException("가짜 PG 서버를 같은 포트로 재시작하지 못했습니다.", e);
            }
        }
    }

    /** 모드 APPROVED, 지연 0, 기록 전부 초기화. 중단된 서버는 같은 포트로 재시작한다. */
    public synchronized void reset() {
        restoreIfStopped();
        mode.set(Mode.APPROVED);
        delayMillis.set(0);
        payCalls.set(0);
        refundCalls.set(0);
        paymentSeq.set(0);
        requests.clear();
        paymentsByKey.clear();
    }

    // ---- 기록 조회 ----

    public int payCallCount() {
        return payCalls.get();
    }

    public int refundCallCount() {
        return refundCalls.get();
    }

    public List<RecordedRequest> requests() {
        return List.copyOf(requests);
    }

    public RecordedRequest lastPayRequest() {
        return lastMatching("/v1/payments");
    }

    public RecordedRequest lastRefundRequest() {
        RecordedRequest last = null;
        for (RecordedRequest r : requests) {
            if (r.path().endsWith("/refund")) {
                last = r;
            }
        }
        return last;
    }

    private RecordedRequest lastMatching(String exactPath) {
        RecordedRequest last = null;
        for (RecordedRequest r : requests) {
            if (r.path().equals(exactPath)) {
                last = r;
            }
        }
        return last;
    }

    /** 서로 다른 Idempotency-Key 로 실제 처리된 결제 건수. */
    public int distinctPaymentCount() {
        return paymentsByKey.size();
    }

    // ---- 내부 ----

    private void bind(int bindPort) throws IOException {
        HttpServer s = HttpServer.create(new InetSocketAddress("localhost", bindPort), 128);
        ExecutorService ex = Executors.newCachedThreadPool(r -> {
            Thread t = new Thread(r, "fake-pg");
            t.setDaemon(true);
            return t;
        });
        s.setExecutor(ex);
        s.createContext("/v1/payments", new PaymentsHandler());
        s.start();
        this.server = s;
        this.executor = ex;
        this.port = s.getAddress().getPort();
    }

    private void shutdown() {
        HttpServer s = this.server;
        ExecutorService ex = this.executor;
        this.server = null;
        this.executor = null;
        if (s != null) {
            s.stop(0);
        }
        if (ex != null) {
            ex.shutdownNow();
        }
    }

    private class PaymentsHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            try (exchange) {
                String path = exchange.getRequestURI().getPath();
                String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
                Map<String, String> headers = new ConcurrentHashMap<>();
                exchange.getRequestHeaders().forEach((k, v) -> {
                    if (!v.isEmpty()) {
                        headers.put(k.toLowerCase(), v.get(0));
                    }
                });
                boolean refund = path.endsWith("/refund");
                if (refund) {
                    refundCalls.incrementAndGet();
                } else {
                    payCalls.incrementAndGet();
                }
                requests.add(new RecordedRequest(exchange.getRequestMethod(), path, headers, body));

                long delay = delayMillis.get();
                if (delay > 0) {
                    try {
                        Thread.sleep(delay);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }

                if (!"POST".equals(exchange.getRequestMethod())) {
                    respond(exchange, 405, "{}");
                    return;
                }
                Mode m = mode.get();
                if (m == Mode.ERROR_5XX) {
                    respond(exchange, 500, "{\"error\":\"pg down\"}");
                    return;
                }
                if (refund) {
                    String paymentId = path.substring("/v1/payments/".length(), path.length() - "/refund".length());
                    respond(exchange, 200, "{\"paymentId\":\"" + paymentId + "\",\"status\":\"REFUNDED\"}");
                    return;
                }
                String key = headers.getOrDefault("idempotency-key", "");
                String result = paymentsByKey.computeIfAbsent(key, k -> {
                    String status = m == Mode.DECLINED ? "DECLINED" : "APPROVED";
                    return "{\"paymentId\":\"pay_" + paymentSeq.incrementAndGet() + "\",\"status\":\"" + status + "\"}";
                });
                respond(exchange, 200, result);
            }
        }

        private void respond(HttpExchange exchange, int status, String json) throws IOException {
            byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length);
