CREATE TABLE products (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR(100) NOT NULL,
    price     BIGINT       NOT NULL,
    stock     INTEGER      NOT NULL,
    reserved  INTEGER      NOT NULL DEFAULT 0,
    CONSTRAINT ck_products_price    CHECK (price BETWEEN 1 AND 10000000),
    CONSTRAINT ck_products_stock    CHECK (stock >= 0),
    CONSTRAINT ck_products_reserved CHECK (reserved >= 0 AND reserved <= stock)
);

CREATE TABLE coupons (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                VARCHAR(20)  NOT NULL,
    discount_type       VARCHAR(10)  NOT NULL,
    discount_value      BIGINT       NOT NULL,
    min_order_amount    BIGINT       NOT NULL DEFAULT 0,
    max_discount_amount BIGINT       NULL,
    total_quantity      INTEGER      NOT NULL,
    used_count          INTEGER      NOT NULL DEFAULT 0,
    valid_from          TIMESTAMPTZ  NOT NULL,
    valid_until         TIMESTAMPTZ  NOT NULL,
    CONSTRAINT uk_coupons_code           UNIQUE (code),
    CONSTRAINT ck_coupons_code           CHECK (code ~ '^[A-Z0-9]{4,20}$'),
    CONSTRAINT ck_coupons_type           CHECK (discount_type IN ('FIXED', 'RATE')),
    CONSTRAINT ck_coupons_value          CHECK (discount_value >= 1 AND (discount_type <> 'RATE' OR discount_value <= 100)),
    CONSTRAINT ck_coupons_min_order      CHECK (min_order_amount >= 0),
    CONSTRAINT ck_coupons_max_discount   CHECK (max_discount_amount IS NULL OR max_discount_amount >= 1),
    CONSTRAINT ck_coupons_total_quantity CHECK (total_quantity >= 1),
    CONSTRAINT ck_coupons_used_count     CHECK (used_count >= 0 AND used_count <= total_quantity),
    CONSTRAINT ck_coupons_period         CHECK (valid_from < valid_until)
);

CREATE TABLE orders (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       VARCHAR(50)  NOT NULL,
    status        VARCHAR(20)  NOT NULL,
    coupon_code   VARCHAR(20)  NULL,
    subtotal      BIGINT       NOT NULL,
    discount      BIGINT       NOT NULL,
    total_price   BIGINT       NOT NULL,
    pg_payment_id VARCHAR(100) NULL,
    created_at    TIMESTAMPTZ  NOT NULL,
    expires_at    TIMESTAMPTZ  NOT NULL,
    paid_at       TIMESTAMPTZ  NULL,
    CONSTRAINT fk_orders_coupon     FOREIGN KEY (coupon_code) REFERENCES coupons (code),
    CONSTRAINT ck_orders_status     CHECK (status IN ('PENDING_PAYMENT', 'PAID', 'PAYMENT_FAILED', 'EXPIRED',
                                                      'CANCELLED', 'SHIPPED', 'DELIVERED', 'REFUNDED')),
    CONSTRAINT ck_orders_subtotal   CHECK (subtotal >= 0),
    CONSTRAINT ck_orders_discount   CHECK (discount >= 0 AND discount <= subtotal),
    CONSTRAINT ck_orders_total      CHECK (total_price = subtotal - discount)
);

CREATE INDEX ix_orders_created_id        ON orders (created_at DESC, id DESC);
CREATE INDEX ix_orders_user_created_id   ON orders (user_id, created_at DESC, id DESC);
CREATE INDEX ix_orders_status_created_id ON orders (status, created_at DESC, id DESC);
CREATE INDEX ix_orders_pending_expires   ON orders (expires_at) WHERE status = 'PENDING_PAYMENT';
CREATE UNIQUE INDEX ux_orders_user_coupon_active
    ON orders (user_id, coupon_code)
    WHERE coupon_code IS NOT NULL
      AND status IN ('PENDING_PAYMENT', 'PAID', 'SHIPPED', 'DELIVERED');

CREATE TABLE order_items (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id   BIGINT  NOT NULL,
    line_no    INTEGER NOT NULL,
    product_id BIGINT  NOT NULL,
    quantity   INTEGER NOT NULL,
    unit_price BIGINT  NOT NULL,
    CONSTRAINT fk_order_items_order   FOREIGN KEY (order_id)   REFERENCES orders (id),
    CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT uk_order_items_line    UNIQUE (order_id, line_no),
    CONSTRAINT uk_order_items_product UNIQUE (order_id, product_id),
    CONSTRAINT ck_order_items_line_no  CHECK (line_no >= 0),
    CONSTRAINT ck_order_items_quantity CHECK (quantity BETWEEN 1 AND 1000),
    CONSTRAINT ck_order_items_price    CHECK (unit_price >= 1)
);

CREATE INDEX ix_order_items_product ON order_items (product_id);

CREATE TABLE idempotency_records (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scope             VARCHAR(20)  NOT NULL,
    idem_key          VARCHAR(64)  NOT NULL,
    fingerprint       VARCHAR(64)  NOT NULL,
    status            VARCHAR(20)  NOT NULL,
    response_status   INTEGER      NULL,
    response_body     TEXT         NULL,
    response_location VARCHAR(255) NULL,
    created_at        TIMESTAMPTZ  NOT NULL,
    completed_at      TIMESTAMPTZ  NULL,
    CONSTRAINT uk_idem_scope_key   UNIQUE (scope, idem_key),
    CONSTRAINT ck_idem_scope       CHECK (scope IN ('CREATE_ORDER', 'PAY_ORDER')),
    CONSTRAINT ck_idem_status      CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
    CONSTRAINT ck_idem_completed   CHECK (status <> 'COMPLETED'
                                          OR (response_status IS NOT NULL AND response_body IS NOT NULL))
);
package com.example.order.common.error;

import jakarta.validation.ConstraintViolationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.MediaType;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

@RestControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ProblemDetail> handleApi(ApiException ex) {
        return build(ex.code(), ex.getMessage());
    }

    @ExceptionHandler(ConstraintViolationException.class)
    public ResponseEntity<ProblemDetail> handleConstraintViolation(ConstraintViolationException ex) {
        return build(ErrorCode.VALIDATION_ERROR, "요청 검증에 실패했습니다.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ProblemDetail> handleUnexpected(Exception ex) {
        log.error("Unexpected error", ex);
        return build(ErrorCode.INTERNAL_ERROR, "예상치 못한 오류가 발생했습니다.");
    }

    /** Spring MVC 표준 예외(검증·바인딩·파싱 실패 등)의 400 응답에 code=VALIDATION_ERROR를 부여한다. */
    @Override
    protected ResponseEntity<Object> handleExceptionInternal(
            Exception ex, Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
        ResponseEntity<Object> response = super.handleExceptionInternal(ex, body, headers, statusCode, request);
        if (response != null && response.getBody() instanceof ProblemDetail pd && statusCode.value() == 400) {
            apply(pd, ErrorCode.VALIDATION_ERROR);
        }
        return response;
    }

    private static ResponseEntity<ProblemDetail> build(ErrorCode code, String detail) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(code.status(), detail);
        apply(pd, code);
        return ResponseEntity.status(code.status())
                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
                .body(pd);
    }

    private static void apply(ProblemDetail pd, ErrorCode code) {
        pd.setType(java.net.URI.create(code.typeUri()));
        pd.setTitle(code.title());
        pd.setProperty("code", code.name());
    }
}
package com.example.order.common.error;

import org.springframework.http.HttpStatus;

public enum ErrorCode {
    VALIDATION_ERROR(HttpStatus.BAD_REQUEST, "Validation error"),
    PAYMENT_DECLINED(HttpStatus.PAYMENT_REQUIRED, "Payment declined"),
    PRODUCT_NOT_FOUND(HttpStatus.NOT_FOUND, "Product not found"),
    COUPON_NOT_FOUND(HttpStatus.NOT_FOUND, "Coupon not found"),
    ORDER_NOT_FOUND(HttpStatus.NOT_FOUND, "Order not found"),
    INSUFFICIENT_STOCK(HttpStatus.CONFLICT, "Insufficient stock"),
    COUPON_NOT_APPLICABLE(HttpStatus.CONFLICT, "Coupon not applicable"),
    COUPON_EXHAUSTED(HttpStatus.CONFLICT, "Coupon exhausted"),
    DUPLICATE_COUPON_CODE(HttpStatus.CONFLICT, "Duplicate coupon code"),
    INVALID_STATE(HttpStatus.CONFLICT, "Invalid state"),
    IDEMPOTENCY_IN_PROGRESS(HttpStatus.CONFLICT, "Idempotency request in progress"),
    IDEMPOTENCY_KEY_MISMATCH(HttpStatus.UNPROCESSABLE_ENTITY, "Idempotency key mismatch"),
    PAYMENT_GATEWAY_UNAVAILABLE(HttpStatus.SERVICE_UNAVAILABLE, "Payment gateway unavailable"),
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR, "Internal error");

    private final HttpStatus status;
    private final String title;

    ErrorCode(HttpStatus status, String title) {
        this.status = status;
        this.title = title;
    }

    public HttpStatus status() {
        return status;
    }

    public String title() {
        return title;
    }

    public String typeUri() {
        return "https://api.example.com/problems/" + name().toLowerCase().replace('_', '-');
    }
}
