    @DisplayName("R10.2 totalQuantity 5 쿠폰을 서로 다른 사용자 15명이 동시에 사용 -> 정확히 5건 201, 10건 409, 최종 usedCount 5")
    void r10_2_couponQuantityNeverExceeded() {
